def load() -> pd.DataFrame:
    import glob
    dfs = []
    for f in sorted(glob.glob('data/environment/input/monthly_precipitations_*.csv')):
        city = f.split('/')[-1].replace('monthly_precipitations_', '').replace('.csv', '').title()
        df = pd.read_csv(f)
        df['City'] = city
        dfs.append(df)
    return pd.concat(dfs, ignore_index=True)

def process(precip_combined) -> pd.DataFrame:
    df = precip_combined[precip_combined['Year'].notna()].copy()
    df['Year'] = pd.to_numeric(df['Year'], errors='coerce')
    df = df[df['Year'].notna()].copy()
    df = df[(df['Year'] >= 2007) & (df['Year'] <= 2009)]

    for month in ['Jun', 'Jul', 'Aug']:
        df[month] = pd.to_numeric(df[month], errors='coerce')

    return df[['Year', 'City', 'Jun', 'Jul', 'Aug']].reset_index(drop=True)
